import path from 'node:path';
import { mkdir, rename } from 'node:fs/promises';
const source = 'report.csv';
const extensionFolder = path.extname(source).slice(1) || 'no-extension';
const destination = path.join('organized', extensionFolder, path.basename(source));
async function organize(dryRun = true) {
  if (dryRun) { console.log(`Would move ${source} to ${destination}`); return; }
  await mkdir(path.dirname(destination), { recursive: true });
  await rename(source, destination);
}
await organize(true);
